const place = ([name, lat, lng]: Row): Place => ({ name, lat, lng });

export const PROVINCES: string[] = DATA.map(([p]) => p[0]);

/** The province's centre (its city centre). */
export function provinceCentre(province: string): Place | null {
  const row = DATA.find(([p]) => p[0] === province);
  return row ? place(row[0]) : null;
}

/** The province's districts, each with a point inside it. */
export function districtsOf(province: string): Place[] {
  return DATA.find(([p]) => p[0] === province)?.[1].map(place) ?? [];
}
